SELECT a.STATUS, a.BUSI_ID, a.START_DATE as startDate, a.CASH_TYPE2, a.RATE, a.CREATE_USER, a.CREATE_TIME as createTime, a.UPDATE_USER, a.UPDATE_TIME as updateTime, '' as datauuid, a.SVR_DATA_SOURCES as dataSource FROM REP_CASH_YIELD a LEFT JOIN chb_prd_baseinfo b on a.BUSI_ID=b.PROD_ID
not EXISTS ( SELECT 1 from REP_CASH_YIELD_ERRORDATA c where c.PROD_ID=a.BUSI_ID and c.CASH_TYPE_2=a.CASH_TYPE2 and c.START_DATE=a.START_DATE and c.STATUS in('A','E') )
#{busiId,jdbcType=VARCHAR}
#{cashType2,jdbcType=VARCHAR}
#{status,jdbcType=VARCHAR}
union all SELECT 'A' as 数据状态, c.PROD_ID, c.START_DATE as startDate, c.CASH_TYPE_2, c.FEE_RATE, c.CREATE_USER, c.CREATE_TIME as createTime, c.UPDATE_USER, c.UPDATE_TIME as updateTime, c.DATAUUID as datauuid, 'DB' as dataSource FROM REP_CASH_YIELD_ERRORDATA c LEFT JOIN chb_prd_baseinfo d on c.PROD_ID=d.PROD_ID
c.STATUS in('A','E')
and c.PROD_ID in(#{busiId})
and c.CASH_TYPE_2 in(#{cashType2})
and 1 = 2

SELECT p.prod_id,p.prod_name FROM chb_prd_baseinfo p where p.status in ('E')
AND P.PROD_ID LIKE concat_ws(concat_ws('%', #{search}),'%') or p.prod_name like concat_ws(concat_ws('%', #{search}),'%')
AND P.PROD_ID = #{initValue}

	SELECT count(1) from (
SELECT 1 from REP_CASH_YIELD a
	where a.STATUS in('A','E')
	and not EXISTS (
	 SELECT 1 from 	REP_CASH_YIELD_ERRORDATA b
			WHERE b.PROD_ID=a.BUSI_ID
				and b.CASH_TYPE_2=a.CASH_TYPE2
			and b.START_DATE=a.START_DATE
			and b.STATUS in('A','E')
	) and

	a.BUSI_ID = #{item.busiId,jdbcType=VARCHAR}
	and a.START_DATE = #{item.startDate,jdbcType=DATE}
	and a.CASH_TYPE2 = #{item.cashType2,jdbcType=VARCHAR}


	union all
	SELECT 1 from rep_cash_yield_errordata c
	where c.STATUS in('A','E')
and

	c.PROD_ID = #{item.busiId,jdbcType=VARCHAR}
	and c.START_DATE = #{item.startDate,jdbcType=DATE}
	and c.CASH_TYPE_2 = #{item.cashType2,jdbcType=VARCHAR}


