set
STATUS = "D"
where

	BUSI_ID = #{item.busiId,jdbcType=VARCHAR}
	AND START_DATE = #{item.startDate,jdbcType=DATE}
	AND CASH_TYPE2 = #{item.cashType2,jdbcType=VARCHAR}
